-- ================================================================
-- 067_seed_interacoes_musculoesqueleticas.sql
-- Secção 9 (Aparelho osteoarticular): 9.1 AINE; 9.2 Modificadores da
-- evolução da doença reumática; 9.3 Medicamentos para a gota;
-- 9.4 Medicamentos para a artrose; 9.6 Osso e metabolismo do cálcio.
-- (9.5 Enzimas anti-inflamatórias: tópicos/inespecíficos — sem fármaco
-- sistémico novo, fora do âmbito.)
-- Novos (8): naproxeno, celecoxib, metotrexato, leflunomida, colchicina,
--            febuxostat, alendronato, calcitriol.
-- Extensão 3 dimensões (existentes): aspirina, ibuprofeno, diclofenac,
--            alopurinol, azatioprina, prednisolona, hidroxicloroquina.
-- Aplicar manualmente no Supabase (SQL editor). Idempotente (ON CONFLICT).
-- Fonte fármaco-fármaco: DailyMed (FDA) — setIDs validados na API.
-- Fonte 3 dimensões: EMC-UK (MHRA) canónico; fallback DailyMed (FDA).
-- ================================================================

-- ----------------------------------------------------------------
-- 1. Fármacos novos
-- ----------------------------------------------------------------
INSERT INTO public.drugs (slug, name_pt, name_en, class_pt, class_en, aliases, status, sort_order) VALUES
  ('naproxeno', 'Naproxeno', 'Naproxen', 'AINE não seletivo (anti-inflamatório/analgésico)', 'Non-steroidal anti-inflammatory (NSAID)', ARRAY['Naprosyn', 'Aleve', 'naproxeno sódico', 'naproxen'], 'published', 151),
  ('celecoxib', 'Celecoxib', 'Celecoxib', 'AINE seletivo COX-2 (coxibe)', 'Selective COX-2 NSAID (coxib)', ARRAY['Celebrex', 'celecoxib'], 'published', 152),
  ('metotrexato', 'Metotrexato', 'Methotrexate', 'DMARD anti-metabólito (antifólico)', 'DMARD anti-metabolite (antifolate)', ARRAY['Methotrexate', 'metotrexato'], 'published', 153),
  ('leflunomida', 'Leflunomida', 'Leflunomide', 'DMARD (inibidor da síntese de pirimidinas)', 'DMARD (pyrimidine synthesis inhibitor)', ARRAY['Arava', 'leflunomida', 'leflunomide'], 'published', 154),
  ('colchicina', 'Colchicina', 'Colchicine', 'Alcaloide antigotoso (anti-inflamatório dos microtúbulos)', 'Antigout alkaloid (anti-inflammatory via microtubules)', ARRAY['colchicine', 'Yuzu'], 'published', 155),
  ('febuxostat', 'Febuxostat', 'Febuxostat', 'Inibidor da xantina-oxidase (redutor da uricemia)', 'Xanthine oxidase inhibitor (uric-lowering)', ARRAY['Adenuric', 'febuxostat'], 'published', 156),
  ('alendronato', 'Alendronato sódico', 'Sodium alendronate', 'Bifosfonato (anti-reabsortivo ósseo)', 'Bisphosphonate (anti-resorptive)', ARRAY['Fosamax', 'ácido alendrónico', 'alendronic acid', 'sodium alendronate'], 'published', 157),
  ('calcitriol', 'Calcitriol', 'Calcitriol', 'Hormona da vitamina D (regulação do cálcio/fósforo)', 'Vitamin D hormone (calcium/phosphate regulation)', ARRAY['Rocaltrol', 'calcitriol', '1,25-dihidroxicolecalciferol', 'alatrofisterol'], 'published', 158);

-- ----------------------------------------------------------------
-- 2. Fármaco-fármaco (drug_interactions)
-- ----------------------------------------------------------------
INSERT INTO public.drug_interactions
  (drug_a_id, drug_b_id, severity, summary_pt, summary_en, mechanism_pt, mechanism_en,
   management_pt, management_en, monitoring_pt, monitoring_en, red_flags_pt, red_flags_en,
   source_pt, source_en, status)
SELECT LEAST(a.id, b.id), GREATEST(a.id, b.id), v.severity, v.summary_pt, v.summary_en,
       v.mechanism_pt, v.mechanism_en, v.management_pt, v.management_en,
       v.monitoring_pt, v.monitoring_en, v.red_flags_pt, v.red_flags_en,
       v.source_pt, v.source_en, 'published'
FROM (VALUES
  ('naproxeno', 'warfarina', 'moderate', 'AINE + anticoagulante: aumento do risco hemorrágico (gastrointestinal e sistémico).', 'NSAID + anticoagulant: increased bleeding risk (gastrointestinal and systemic).', 'Os AINE inibem a COX e a agregação plaquetária e podem deslocar a Varfarina da ligação proteica, potenciando o efeito anticoagulante.', 'NSAIDs inhibit COX and platelet aggregation and may displace warfarin from protein binding, enhancing anticoagulation.', 'Usar a menor dose de AINE pelo menor tempo; considerar gastroprotecção (IBP). Vigiar sinais de hemorragia.', 'Use the lowest NSAID dose for the shortest time; consider gastroprotection (PPI). Watch for signs of bleeding.', 'INR com maior frequência durante a introdução do AINE; avaliar hemograma e sintomas digestivos.', 'More frequent INR monitoring when starting the NSAID; assess full blood count and GI symptoms.', 'Sangue nas fezes/melena, hematemese, hemorragia cutânea ou mucosas.', 'Blood in stools/melena, haematemesis, skin or mucosal bleeding.', 'DailyMed (FDA) — rótulo aprovado Naproxeno: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=24d44eb6-921e-4150-a6b2-81f42ced32ab ; rótulo aprovado Varfarina: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=541c9a70-adaf-4ef3-94ba-ad4e70dfa057 — referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)', 'DailyMed (FDA) — approved Naproxen label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=24d44eb6-921e-4150-a6b2-81f42ced32ab ; approved Warfarin label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=541c9a70-adaf-4ef3-94ba-ad4e70dfa057 — additional reference: Prontuário Terapêutico do INFARMED (11th ed., 2012)'),
  ('naproxeno', 'litio', 'moderate', 'AINE + lítio: risco de aumento da litemia e toxicidade pelo lítio.', 'NSAID + lithium: risk of raised serum lithium and lithium toxicity.', 'Os AINE reduzem a depuração renal do lítio (redução da excreção), elevando a litemia.', 'NSAIDs reduce renal lithium clearance (decreased excretion), raising lithium levels.', 'Suspender ou reduzir o AINE com monitorização da litemia; vigiar sinais de toxicidade do lítio.', 'Stop or reduce the NSAID with serum lithium monitoring; watch for signs of lithium toxicity.', 'Litemia e função renal durante a terapêutica combinada.', 'Serum lithium and renal function during combined therapy.', 'Náuseas, confusão, tremor, sinais de neurotoxicidade; arritmias.', 'Nausea, confusion, tremor, signs of neurotoxicity; arrhythmias.', 'DailyMed (FDA) — rótulo aprovado Naproxeno: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=24d44eb6-921e-4150-a6b2-81f42ced32ab ; rótulo aprovado Lítio: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=582697c1-063f-366f-e063-6294a90a8d1b — referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)', 'DailyMed (FDA) — approved Naproxen label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=24d44eb6-921e-4150-a6b2-81f42ced32ab ; approved Lithium label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=582697c1-063f-366f-e063-6294a90a8d1b — additional reference: Prontuário Terapêutico do INFARMED (11th ed., 2012)'),
  ('naproxeno', 'prednisolona', 'moderate', 'Corticosteroide + AINE: risco gastrointestinal (úlcera/hemorragia) aditivo.', 'Corticosteroid + NSAID: additive gastrointestinal risk (ulcer/bleeding).', 'Ambos enfraquecem a proteção da mucosa gástrica e aumentam o risco de úlcera e hemorragia GI.', 'Both weaken gastric mucosal protection and increase the risk of GI ulcer and bleeding.', 'Combinar apenas se necessário; considerar gastroprotecção e a menor dose eficaz de ambos.', 'Combine only if necessary; consider gastroprotection and the lowest effective dose of both.', 'Vigiar dispepsia, dor abdominal e sinais de hemorragia digestiva.', 'Watch for dyspepsia, abdominal pain and signs of GI bleeding.', 'Dor abdominal, melena, hematemese.', 'Abdominal pain, melena, haematemesis.', 'DailyMed (FDA) — rótulo aprovado Naproxeno: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=24d44eb6-921e-4150-a6b2-81f42ced32ab ; rótulo aprovado Prednisolona: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=52e6e21d-94b8-41a0-8d13-371c0e66bcee — referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)', 'DailyMed (FDA) — approved Naproxen label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=24d44eb6-921e-4150-a6b2-81f42ced32ab ; approved Prednisolone label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=52e6e21d-94b8-41a0-8d13-371c0e66bcee — additional reference: Prontuário Terapêutico do INFARMED (11th ed., 2012)'),
  ('naproxeno', 'ibuprofeno', 'moderate', 'Dois AINE em simultâneo: sem benefício adicional e com maior risco GI/renal.', 'Two NSAIDs together: no added benefit and increased GI/renal risk.', 'Efeitos aditivos na mucosa gástrica, na função renal e na agregação plaquetária.', 'Additive effects on gastric mucosa, renal function and platelet aggregation.', 'Não combinar AINE; usar um único AINE à menor dose eficaz.', 'Do not combine NSAIDs; use a single NSAID at the lowest effective dose.', 'Função renal e sinais de intolerância gastrointestinal em doentes de risco.', 'Renal function and GI intolerance signs in at-risk patients.', 'Dispepsia, dor epigástrica, oligúria, edema.', 'Dyspepsia, epigastric pain, oliguria, oedema.', 'DailyMed (FDA) — rótulo aprovado Naproxeno: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=24d44eb6-921e-4150-a6b2-81f42ced32ab ; rótulo aprovado Ibuprofeno: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=291602fa-8ebe-4200-bba7-9798c90f8a50 — referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)', 'DailyMed (FDA) — approved Naproxen label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=24d44eb6-921e-4150-a6b2-81f42ced32ab ; approved Ibuprofen label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=291602fa-8ebe-4200-bba7-9798c90f8a50 — additional reference: Prontuário Terapêutico do INFARMED (11th ed., 2012)'),
  ('naproxeno', 'aspirina', 'moderate', 'AINE + aspirina em baixa dose: pode reduzir o efeito cardioprotetor da aspirina e aumentar o risco GI.', 'NSAID + low-dose aspirin: may reduce aspirin cardioprotection and increase GI risk.', 'Os AINE podem ocupar o mesmo local ativo da COX e interferir com a inibição antiagregante irreversível da aspirina.', 'NSAIDs may occupy the same COX active site and interfere with aspirin irreversible antiplatelet inhibition.', 'Tomar a aspirina pelo menos 2 h antes do AINE quando possível; considerar paracetamol para analgesia.', 'Take aspirin at least 2 h before the NSAID when possible; consider paracetamol for analgesia.', 'Reavaliar periodicamente a necessidade da associação e a gastroproteção.', 'Periodically reassess the need for the combination and gastroprotection.', 'Sinais de evento trombótico ou hemorragia GI.', 'Signs of thrombotic event or GI bleeding.', 'DailyMed (FDA) — rótulo aprovado Naproxeno: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=24d44eb6-921e-4150-a6b2-81f42ced32ab ; rótulo aprovado Ácido acetilsalicílico: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=3ba0a9f2-062a-401e-82eb-54383a822366 — referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)', 'DailyMed (FDA) — approved Naproxen label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=24d44eb6-921e-4150-a6b2-81f42ced32ab ; approved Aspirin label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=3ba0a9f2-062a-401e-82eb-54383a822366 — additional reference: Prontuário Terapêutico do INFARMED (11th ed., 2012)'),
  ('celecoxib', 'warfarina', 'moderate', 'Coxib + anticoagulante: aumento do risco hemorrágico.', 'Coxib + anticoagulant: increased bleeding risk.', 'O celecoxib pode aumentar o risco hemorrágico gastrointestinal e interagir com a anticoagulação.', 'Celecoxib may increase gastrointestinal bleeding risk and interact with anticoagulation.', 'Usar com cautela, considerar gastroprotecção e vigiar sinais de hemorragia.', 'Use with caution, consider gastroprotection and watch for bleeding signs.', 'INR e sintomas digestivos durante a associação.', 'INR and GI symptoms during the combination.', 'Melena, hematemese, equimoses espontâneas.', 'Melena, haematemesis, spontaneous ecchymosis.', 'DailyMed (FDA) — rótulo aprovado Celecoxib: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=b06ced10-81c6-4f48-a205-1e0db228cb8b ; rótulo aprovado Varfarina: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=541c9a70-adaf-4ef3-94ba-ad4e70dfa057 — referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)', 'DailyMed (FDA) — approved Celecoxib label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=b06ced10-81c6-4f48-a205-1e0db228cb8b ; approved Warfarin label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=541c9a70-adaf-4ef3-94ba-ad4e70dfa057 — additional reference: Prontuário Terapêutico do INFARMED (11th ed., 2012)'),
  ('celecoxib', 'ibuprofeno', 'moderate', 'Dois AINE (coxib + clássico): sem benefício e com risco GI/renal/ cardiovascular acrescido.', 'Two NSAIDs (coxib + classical): no benefit and added GI/renal/cardiovascular risk.', 'Efeitos adversos aditivos na mucosa gástrica, função renal e equilíbrio cardiovascular.', 'Additive adverse effects on gastric mucosa, renal function and cardiovascular balance.', 'Não combinar AINE; usar um único AINE à menor dose eficaz.', 'Do not combine NSAIDs; use a single NSAID at the lowest effective dose.', 'Função renal, tensão arterial e sintomas GI.', 'Renal function, blood pressure and GI symptoms.', 'Dispepsia, edema, elevação da tensão arterial.', 'Dyspepsia, oedema, raised blood pressure.', 'DailyMed (FDA) — rótulo aprovado Celecoxib: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=b06ced10-81c6-4f48-a205-1e0db228cb8b ; rótulo aprovado Ibuprofeno: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=291602fa-8ebe-4200-bba7-9798c90f8a50 — referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)', 'DailyMed (FDA) — approved Celecoxib label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=b06ced10-81c6-4f48-a205-1e0db228cb8b ; approved Ibuprofen label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=291602fa-8ebe-4200-bba7-9798c90f8a50 — additional reference: Prontuário Terapêutico do INFARMED (11th ed., 2012)'),
  ('metotrexato', 'cotrimoxazol', 'moderate', 'Antifólico + antagonista do folato: o cotrimoxazol potencia a toxicidade do metotrexato.', 'Antifolate + folate antagonist: co-trimoxazole potentiates methotrexate toxicity.', 'O trimetoprim inibe a diidrofolato-redutase e reduz a depuração renal do metotrexato, com risco de mielossupressão grave.', 'Trimethoprim inhibits dihydrofolate reductase and reduces methotrexate renal clearance, risking severe marrow suppression.', 'Evitar a associação quando possível; se inevitável, monitorizar hemograma e função renal com frequência.', 'Avoid the combination when possible; if unavoidable, monitor full blood count and renal function frequently.', 'Hemograma e função renal; reavaliar dose de metotrexato.', 'Full blood count and renal function; reassess methotrexate dose.', 'Febre, infeções, úlceras orais, anemia, leucopenia, trombocitopenia.', 'Fever, infections, oral ulcers, anaemia, leucopenia, thrombocytopenia.', 'DailyMed (FDA) — rótulo aprovado Metotrexato: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=757d6cef-6696-7a1c-8074-01258aaa8bdd ; rótulo aprovado Cotrimoxazol: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=08500fcb-dbec-4ac2-91c3-189d27907ec0 — referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)', 'DailyMed (FDA) — approved Methotrexate label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=757d6cef-6696-7a1c-8074-01258aaa8bdd ; approved Co-trimoxazole label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=08500fcb-dbec-4ac2-91c3-189d27907ec0 — additional reference: Prontuário Terapêutico do INFARMED (11th ed., 2012)'),
  ('metotrexato', 'ciprofloxacina', 'moderate', 'Fluoroquinolona + metotrexato: possível aumento da toxicidade do metotrexato.', 'Fluoroquinolone + methotrexate: possible increased methotrexate toxicity.', 'A ciprofloxacina pode reduzir a depuração renal do metotrexato, elevando as suas concentrações.', 'Ciprofloxacin may reduce methotrexate renal clearance, raising its concentrations.', 'Usar com precaução e monitorizar hemograma e função renal.', 'Use with caution and monitor full blood count and renal function.', 'Hemograma e função renal durante a antibioterapia.', 'Full blood count and renal function during antibiotic therapy.', 'Mielossupressão: febre, úlceras orais, infeções.', 'Marrow suppression: fever, oral ulcers, infections.', 'DailyMed (FDA) — rótulo aprovado Metotrexato: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=757d6cef-6696-7a1c-8074-01258aaa8bdd ; rótulo aprovado Ciprofloxacina: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=c527d138-e32c-418f-9573-a3d8a796279f — referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)', 'DailyMed (FDA) — approved Methotrexate label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=757d6cef-6696-7a1c-8074-01258aaa8bdd ; approved Ciprofloxacin label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=c527d138-e32c-418f-9573-a3d8a796279f — additional reference: Prontuário Terapêutico do INFARMED (11th ed., 2012)'),
  ('metotrexato', 'ibuprofeno', 'moderate', 'AINE + metotrexato: redução da depuração renal e aumento da toxicidade do MTX.', 'NSAID + methotrexate: reduced renal clearance and increased MTX toxicity.', 'Os AINE inibem a excreção renal do metotrexato, elevando as suas concentrações séricas.', 'NSAIDs inhibit renal excretion of methotrexate, raising serum concentrations.', 'Evitar AINE em doentes em metotrexato; se necessário, preferir paracetamol e monitorizar.', 'Avoid NSAIDs in patients on methotrexate; if needed, prefer paracetamol and monitor.', 'Hemograma e função renal; sinais clínicos de toxicidade do MTX.', 'Full blood count and renal function; clinical signs of MTX toxicity.', 'Úlceras orais, mielossupressão, hepatotoxicidade.', 'Oral ulcers, marrow suppression, hepatotoxicity.', 'DailyMed (FDA) — rótulo aprovado Metotrexato: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=757d6cef-6696-7a1c-8074-01258aaa8bdd ; rótulo aprovado Ibuprofeno: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=291602fa-8ebe-4200-bba7-9798c90f8a50 — referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)', 'DailyMed (FDA) — approved Methotrexate label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=757d6cef-6696-7a1c-8074-01258aaa8bdd ; approved Ibuprofen label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=291602fa-8ebe-4200-bba7-9798c90f8a50 — additional reference: Prontuário Terapêutico do INFARMED (11th ed., 2012)'),
  ('metotrexato', 'aspirina', 'moderate', 'Aspirina + metotrexato: possível aumento da toxicidade do metotrexato (depuração renal).', 'Aspirin + methotrexate: possible increased methotrexate toxicity (renal clearance).', 'A aspirina (sobretudo em doses AINE) pode reduzir a depuração renal do metotrexato.', 'Aspirin (especially at NSAID doses) may reduce methotrexate renal clearance.', 'Preferir paracetamol quando possível; monitorizar hemograma se a associação for necessária.', 'Prefer paracetamol when possible; monitor full blood count if the combination is needed.', 'Hemograma e função renal em terapêuticas prolongadas.', 'Full blood count and renal function on long-term therapy.', 'Úlceras orais, sinais de mielossupressão.', 'Oral ulcers, signs of marrow suppression.', 'DailyMed (FDA) — rótulo aprovado Metotrexato: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=757d6cef-6696-7a1c-8074-01258aaa8bdd ; rótulo aprovado Ácido acetilsalicílico: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=3ba0a9f2-062a-401e-82eb-54383a822366 — referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)', 'DailyMed (FDA) — approved Methotrexate label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=757d6cef-6696-7a1c-8074-01258aaa8bdd ; approved Aspirin label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=3ba0a9f2-062a-401e-82eb-54383a822366 — additional reference: Prontuário Terapêutico do INFARMED (11th ed., 2012)'),
  ('azatioprina', 'febuxostat', 'critical', 'Inibidor da xantina-oxidase + azatioprina: risco de mielossupressão grave e potencialmente fatal.', 'Xanthine oxidase inhibitor + azathioprine: risk of severe, potentially fatal marrow suppression.', 'O febuxostat (como o alopurinol) inibe a xantina-oxidase, enzima que degrada o 6-mercaptopurina ativo da azatioprina; os níveis sobem de forma acentuada.', 'Febuxostat (like allopurinol) inhibits xanthine oxidase, the enzyme that degrades the active 6-mercaptopurine from azathioprine; levels rise markedly.', 'Associação contraindicada. Reduzir a dose de azatioprina em cerca de 75% apenas se for clinicamente imprescindível e com monitorização apertada de hemograma.', 'Combination contraindicated. Reduce azathioprine dose by about 75% only if clinically essential, with tight full blood count monitoring.', 'Hemograma semanal nas primeiras semanas de associação.', 'Weekly full blood count in the first weeks of the combination.', 'Febre, infeções graves, pancitopenia, hemorragia.', 'Fever, severe infections, pancytopenia, bleeding.', 'DailyMed (FDA) — rótulo aprovado Azatioprina: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=5116b22b-1460-5535-e063-6394a90acbe5 ; rótulo aprovado Febuxostat: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=f2c338dc-5bab-49f4-a4ac-d8dea8afeea5 — referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)', 'DailyMed (FDA) — approved Azathioprine label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=5116b22b-1460-5535-e063-6394a90acbe5 ; approved Febuxostat label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=f2c338dc-5bab-49f4-a4ac-d8dea8afeea5 — additional reference: Prontuário Terapêutico do INFARMED (11th ed., 2012)'),
  ('colchicina', 'claritromicina', 'critical', 'Colchicina + inibidor potente do CYP3A4/P-gp: risco de toxicidade grave da colchicina.', 'Colchicine + potent CYP3A4/P-gp inhibitor: risk of severe colchicine toxicity.', 'A claritromicina inibe o CYP3A4 e a glicoproteína-P, aumentando muito as concentrações de colchicina.', 'Clarithromycin inhibits CYP3A4 and P-glycoprotein, markedly raising colchicine concentrations.', 'Associação contraindicada; preferir alternativa antibiótica. Se inevitável, reduzir fortemente a dose de colchicina.', 'Contraindicated; prefer an alternative antibiotic. If unavoidable, strongly reduce the colchicine dose.', 'Vigiar sintomas de toxicidade da colchicina (GI, neuromuscular).', 'Watch for colchicine toxicity symptoms (GI, neuromuscular).', 'Diarreia grave, vómitos, rabdomiólise, pancitopenia, arritmias.', 'Severe diarrhoea, vomiting, rhabdomyolysis, pancytopenia, arrhythmias.', 'DailyMed (FDA) — rótulo aprovado Colchicina: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=5ae87893-a065-468e-b8da-f1db86afcaef ; rótulo aprovado Claritromicina: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=d836ae7e-fdbf-4dcb-a90d-ede1dcbc3e67 — referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)', 'DailyMed (FDA) — approved Colchicine label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=5ae87893-a065-468e-b8da-f1db86afcaef ; approved Clarithromycin label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=d836ae7e-fdbf-4dcb-a90d-ede1dcbc3e67 — additional reference: Prontuário Terapêutico do INFARMED (11th ed., 2012)'),
  ('colchicina', 'atorvastatina', 'moderate', 'Colchicina + estatina: risco aumentado de miopatia/rabdomiólise.', 'Colchicine + statin: increased risk of myopathy/rhabdomyolysis.', 'Efeito aditivo sobre o músculo esquelético, sobretudo em doentes com função renal reduzida.', 'Additive effect on skeletal muscle, especially in patients with reduced renal function.', 'Vigiar sintomas musculares; considerar reduzir a dose de colchicina ou suspender a estatina.', 'Watch for muscle symptoms; consider reducing colchicine or stopping the statin.', 'CPK e função renal em doentes sintomáticos.', 'CPK and renal function in symptomatic patients.', 'Mialgias, fraqueza muscular, urina escura.', 'Myalgia, muscle weakness, dark urine.', 'DailyMed (FDA) — rótulo aprovado Colchicina: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=5ae87893-a065-468e-b8da-f1db86afcaef ; rótulo aprovado Atorvastatina: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=fbd1c5da-67fb-4412-acb5-4d4c74a43654 — referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)', 'DailyMed (FDA) — approved Colchicine label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=5ae87893-a065-468e-b8da-f1db86afcaef ; approved Atorvastatin label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=fbd1c5da-67fb-4412-acb5-4d4c74a43654 — additional reference: Prontuário Terapêutico do INFARMED (11th ed., 2012)'),
  ('colchicina', 'warfarina', 'moderate', 'Colchicina + anticoagulante: possível aumento do efeito anticoagulante.', 'Colchicine + anticoagulant: possible increased anticoagulant effect.', 'A colchicina pode interferir com o metabolismo/efeito da varfarina, com elevação do INR.', 'Colchicine may interfere with warfarin metabolism/effect, raising INR.', 'Monitorizar INR após introdução ou alteração de dose de colchicina.', 'Monitor INR after starting or changing colchicine dose.', 'INR periódico durante a associação.', 'Periodic INR during the combination.', 'Hemorragia, equimoses espontâneas.', 'Bleeding, spontaneous ecchymosis.', 'DailyMed (FDA) — rótulo aprovado Colchicina: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=5ae87893-a065-468e-b8da-f1db86afcaef ; rótulo aprovado Varfarina: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=541c9a70-adaf-4ef3-94ba-ad4e70dfa057 — referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)', 'DailyMed (FDA) — approved Colchicine label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=5ae87893-a065-468e-b8da-f1db86afcaef ; approved Warfarin label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=541c9a70-adaf-4ef3-94ba-ad4e70dfa057 — additional reference: Prontuário Terapêutico do INFARMED (11th ed., 2012)'),
  ('alendronato', 'antiacidos', 'moderate', 'Bifosfonato + antiácidos: redução marcada da absorção do alendronato.', 'Bisphosphonate + antacids: marked reduction of alendronate absorption.', 'O cálcio, alumínio e magnésio dos antiácidos quelam o alendronato no trato GI, impedindo a absorção.', 'Calcium, aluminium and magnesium in antacids chelate alendronate in the GI tract, preventing absorption.', 'Separar a toma por pelo menos 2 horas (alendronato em jejum, com água simples).', 'Separate administration by at least 2 hours (alendronate on an empty stomach, with plain water).', 'Confirmar a adesão ao esquema de toma correto.', 'Confirm adherence to the correct dosing schedule.', 'Falta de efeito terapêutico; persistência da osteoporose/dor óssea.', 'Lack of therapeutic effect; persisting osteoporosis/bone pain.', 'DailyMed (FDA) — rótulo aprovado Alendronato: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=c7e470d6-508e-466e-a78d-060bbbc9745c ; rótulo aprovado Antiácidos: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=5e346dc0-69ce-4cc5-bb5d-bfa833e11c1f — referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)', 'DailyMed (FDA) — approved Alendronate label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=c7e470d6-508e-466e-a78d-060bbbc9745c ; approved Antacids label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=5e346dc0-69ce-4cc5-bb5d-bfa833e11c1f — additional reference: Prontuário Terapêutico do INFARMED (11th ed., 2012)'),
  ('alendronato', 'ibuprofeno', 'moderate', 'Bifosfonato + AINE: risco gastrointestinal aditivo.', 'Bisphosphonate + NSAID: additive gastrointestinal risk.', 'Ambos podem irritar a mucosa esofagogástrica.', 'Both may irritate the oesophagogastric mucosa.', 'Vigiar sintomas digestivos; considerar gastroprotecção se fatores de risco.', 'Watch for GI symptoms; consider gastroprotection if risk factors exist.', 'Sintomas GI (dispepsia, dor, disfagia).', 'GI symptoms (dyspepsia, pain, dysphagia).', 'Dor epigástrica, disfagia, melena.', 'Epigastric pain, dysphagia, melena.', 'DailyMed (FDA) — rótulo aprovado Alendronato: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=c7e470d6-508e-466e-a78d-060bbbc9745c ; rótulo aprovado Ibuprofeno: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=291602fa-8ebe-4200-bba7-9798c90f8a50 — referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)', 'DailyMed (FDA) — approved Alendronate label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=c7e470d6-508e-466e-a78d-060bbbc9745c ; approved Ibuprofen label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=291602fa-8ebe-4200-bba7-9798c90f8a50 — additional reference: Prontuário Terapêutico do INFARMED (11th ed., 2012)'),
  ('alendronato', 'omeprazol', 'moderate', 'Bifosfonato + IBP: possível redução da absorção e do efeito do alendronato.', 'Bisphosphonate + PPI: possible reduced alendronate absorption and effect.', 'A supressão ácida pode reduzir a dissolução/absorção do alendronato.', 'Acid suppression may reduce alendronate dissolution/absorption.', 'Assegurar o esquema correto (jejum + água) e reavaliar a necessidade de IBP.', 'Ensure correct schedule (fasting + water) and reassess the need for the PPI.', 'Avaliar adesão e resposta terapêutica.', 'Assess adherence and therapeutic response.', 'Fratura ou ausência de melhoria densitométrica.', 'Fracture or lack of densitometric improvement.', 'DailyMed (FDA) — rótulo aprovado Alendronato: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=c7e470d6-508e-466e-a78d-060bbbc9745c ; rótulo aprovado Omeprazol: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=6ea9a6f3-b756-4cdf-b3db-f666a2c17d66 — referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)', 'DailyMed (FDA) — approved Alendronate label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=c7e470d6-508e-466e-a78d-060bbbc9745c ; approved Omeprazole label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=6ea9a6f3-b756-4cdf-b3db-f666a2c17d66 — additional reference: Prontuário Terapêutico do INFARMED (11th ed., 2012)'),
  ('calcitriol', 'digoxina', 'moderate', 'Calcitriol + digoxina: a hipercalcémia potenciada pelo calcitriol aumenta o risco de toxicidade digitálica.', 'Calcitriol + digoxin: calcitriol-enhanced hypercalcaemia increases the risk of digitalis toxicity.', 'O calcitriol aumenta a absorção de cálcio; a hipercalcémia sensibiliza o miocárdio à digoxina.', 'Calcitriol increases calcium absorption; hypercalcaemia sensitises the myocardium to digoxin.', 'Monitorizar calcemia e sinais de toxicidade digitálica; ajustar dose de digoxina se necessário.', 'Monitor serum calcium and signs of digoxin toxicity; adjust digoxin dose if needed.', 'Calcemia, função renal, eletrocardiograma.', 'Serum calcium, renal function, ECG.', 'Náuseas, arritmias, visão a cores alterada, confusão.', 'Nausea, arrhythmias, altered colour vision, confusion.', 'DailyMed (FDA) — rótulo aprovado Calcitriol: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=8465337c-86ca-ea9d-e053-2991aa0ab167 ; rótulo aprovado Digoxina: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=e61d2108-d871-44c0-b12a-2e61fbb56967 — referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)', 'DailyMed (FDA) — approved Calcitriol label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=8465337c-86ca-ea9d-e053-2991aa0ab167 ; approved Digoxin label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=e61d2108-d871-44c0-b12a-2e61fbb56967 — additional reference: Prontuário Terapêutico do INFARMED (11th ed., 2012)'),
  ('calcitriol', 'hidroclorotiazida', 'moderate', 'Calcitriol + tiazida: risco de hipercalcémia (redução da excreção renal de cálcio).', 'Calcitriol + thiazide: risk of hypercalcaemia (reduced renal calcium excretion).', 'As tiazidas reduzem a excreção urinária de cálcio, o que se adiciona ao efeito hipercalcémico do calcitriol.', 'Thiazides reduce urinary calcium excretion, adding to the hypercalcaemic effect of calcitriol.', 'Monitorizar calcemia, sobretudo nas primeiras semanas e em doentes com insuficiência renal.', 'Monitor serum calcium, especially in the first weeks and in renal impairment.', 'Calcemia e função renal periodicamente.', 'Serum calcium and renal function periodically.', 'Poliúria, obstipação, confusão, litíase renal.', 'Polyuria, constipation, confusion, renal stones.', 'DailyMed (FDA) — rótulo aprovado Calcitriol: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=8465337c-86ca-ea9d-e053-2991aa0ab167 ; rótulo aprovado Hidroclorotiazida: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=0789baef-3424-43ab-a3fb-4908172da565 — referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)', 'DailyMed (FDA) — approved Calcitriol label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=8465337c-86ca-ea9d-e053-2991aa0ab167 ; approved Hydrochlorothiazide label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=0789baef-3424-43ab-a3fb-4908172da565 — additional reference: Prontuário Terapêutico do INFARMED (11th ed., 2012)'),
  ('calcitriol', 'furosemida', 'minor', 'Calcitriol + diurético de ansa: efeitos contrários sobre a calcemia.', 'Calcitriol + loop diuretic: opposing effects on serum calcium.', 'A furosemida aumenta a excreção renal de cálcio, contrariando em parte o efeito do calcitriol.', 'Furosemide increases renal calcium excretion, partially counteracting calcitriol.', 'Monitorizar calcemia se associação prolongada, especialmente em insuficiência renal.', 'Monitor serum calcium on prolonged combination, especially in renal impairment.', 'Calcemia na terapêutica prolongada.', 'Serum calcium on long-term therapy.', 'Cãibras, parestesias (hipocalcémia).', 'Cramps, paraesthesia (hypocalcaemia).', 'DailyMed (FDA) — rótulo aprovado Calcitriol: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=8465337c-86ca-ea9d-e053-2991aa0ab167 ; rótulo aprovado Furosemida: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=6d9caaab-d874-4cf1-b9fe-408452a18998 — referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)', 'DailyMed (FDA) — approved Calcitriol label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=8465337c-86ca-ea9d-e053-2991aa0ab167 ; approved Furosemide label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=6d9caaab-d874-4cf1-b9fe-408452a18998 — additional reference: Prontuário Terapêutico do INFARMED (11th ed., 2012)'),
  ('prednisolona', 'warfarina', 'moderate', 'Corticosteroide + anticoagulante: alteração do INR e risco hemorrágico.', 'Corticosteroid + anticoagulant: altered INR and bleeding risk.', 'Os corticosteroides podem potenciar ou reduzir o efeito da varfarina (efeito variável sobre a hemostase e a mucosa GI).', 'Corticosteroids may potentiate or reduce warfarin effect (variable effect on haemostasis and GI mucosa).', 'Monitorizar INR após início/ajuste de corticosteroide; considerar gastroprotecção.', 'Monitor INR after starting/adjusting corticosteroids; consider gastroprotection.', 'INR periódico e sintomas digestivos.', 'Periodic INR and GI symptoms.', 'Melena, hematemese, hemorragia.', 'Melena, haematemesis, bleeding.', 'DailyMed (FDA) — rótulo aprovado Prednisolona: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=52e6e21d-94b8-41a0-8d13-371c0e66bcee ; rótulo aprovado Varfarina: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=541c9a70-adaf-4ef3-94ba-ad4e70dfa057 — referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)', 'DailyMed (FDA) — approved Prednisolone label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=52e6e21d-94b8-41a0-8d13-371c0e66bcee ; approved Warfarin label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=541c9a70-adaf-4ef3-94ba-ad4e70dfa057 — additional reference: Prontuário Terapêutico do INFARMED (11th ed., 2012)'),
  ('prednisolona', 'furosemida', 'moderate', 'Corticosteroide + diurético de ansa: risco de hipocaliemia aditiva.', 'Corticosteroid + loop diuretic: additive hypokalaemia risk.', 'Ambos aumentam a perda renal de potássio.', 'Both increase renal potassium loss.', 'Monitorizar o potássio sérico; considerar suplementação se necessário.', 'Monitor serum potassium; consider supplementation if needed.', 'Potássio sérico e sintomas de hipocaliemia.', 'Serum potassium and hypokalaemia symptoms.', 'Fraqueza, cãibras, arritmias.', 'Weakness, cramps, arrhythmias.', 'DailyMed (FDA) — rótulo aprovado Prednisolona: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=52e6e21d-94b8-41a0-8d13-371c0e66bcee ; rótulo aprovado Furosemida: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=6d9caaab-d874-4cf1-b9fe-408452a18998 — referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)', 'DailyMed (FDA) — approved Prednisolone label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=52e6e21d-94b8-41a0-8d13-371c0e66bcee ; approved Furosemide label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=6d9caaab-d874-4cf1-b9fe-408452a18998 — additional reference: Prontuário Terapêutico do INFARMED (11th ed., 2012)'),
  ('prednisolona', 'hidroclorotiazida', 'moderate', 'Corticosteroide + tiazida: hipocaliemia e hiperglicemia aditivas.', 'Corticosteroid + thiazide: additive hypokalaemia and hyperglycaemia.', 'Ambos favorecem a perda de potássio e a elevação da glicemia.', 'Both promote potassium loss and raised blood glucose.', 'Monitorizar potássio e glicemia; ajustar terapêutica se necessário.', 'Monitor potassium and blood glucose; adjust therapy if needed.', 'Potássio, glicemia e tensão arterial.', 'Potassium, blood glucose and blood pressure.', 'Fraqueza, cãibras, poliúria, descompensação glicémica.', 'Weakness, cramps, polyuria, glycaemic decompensation.', 'DailyMed (FDA) — rótulo aprovado Prednisolona: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=52e6e21d-94b8-41a0-8d13-371c0e66bcee ; rótulo aprovado Hidroclorotiazida: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=0789baef-3424-43ab-a3fb-4908172da565 — referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)', 'DailyMed (FDA) — approved Prednisolone label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=52e6e21d-94b8-41a0-8d13-371c0e66bcee ; approved Hydrochlorothiazide label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=0789baef-3424-43ab-a3fb-4908172da565 — additional reference: Prontuário Terapêutico do INFARMED (11th ed., 2012)'),
  ('diclofenac', 'warfarina', 'moderate', 'AINE + anticoagulante: aumento do risco hemorrágico.', 'NSAID + anticoagulant: increased bleeding risk.', 'O diclofenac inibe a COX, a agregação plaquetária e pode interagir com a varfarina, potenciando a anticoagulação.', 'Diclofenac inhibits COX and platelet aggregation and may interact with warfarin, enhancing anticoagulation.', 'Usar a menor dose de AINE possível; considerar gastroprotecção e vigiar hemorragias.', 'Use the lowest NSAID dose; consider gastroprotection and watch for bleeding.', 'INR e sintomas digestivos.', 'INR and GI symptoms.', 'Melena, hematemese, equimoses.', 'Melena, haematemesis, ecchymosis.', 'DailyMed (FDA) — rótulo aprovado Diclofenac: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=2d45648f-cbea-41a4-8e3e-007b7bb7912c ; rótulo aprovado Varfarina: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=541c9a70-adaf-4ef3-94ba-ad4e70dfa057 — referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)', 'DailyMed (FDA) — approved Diclofenac label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=2d45648f-cbea-41a4-8e3e-007b7bb7912c ; approved Warfarin label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=541c9a70-adaf-4ef3-94ba-ad4e70dfa057 — additional reference: Prontuário Terapêutico do INFARMED (11th ed., 2012)'),
  ('diclofenac', 'naproxeno', 'moderate', 'Dois AINE em simultâneo: sem benefício e com risco GI/renal acrescido.', 'Two NSAIDs together: no benefit and increased GI/renal risk.', 'Efeitos aditivos sobre a mucosa gástrica e a função renal.', 'Additive effects on gastric mucosa and renal function.', 'Não combinar AINE; usar um único AINE à menor dose eficaz.', 'Do not combine NSAIDs; use a single NSAID at the lowest effective dose.', 'Função renal e sintomas GI.', 'Renal function and GI symptoms.', 'Dispepsia, dor epigástrica, edema.', 'Dyspepsia, epigastric pain, oedema.', 'DailyMed (FDA) — rótulo aprovado Diclofenac: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=2d45648f-cbea-41a4-8e3e-007b7bb7912c ; rótulo aprovado Naproxeno: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=24d44eb6-921e-4150-a6b2-81f42ced32ab — referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)', 'DailyMed (FDA) — approved Diclofenac label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=2d45648f-cbea-41a4-8e3e-007b7bb7912c ; approved Naproxen label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=24d44eb6-921e-4150-a6b2-81f42ced32ab — additional reference: Prontuário Terapêutico do INFARMED (11th ed., 2012)'),
  ('alopurinol', 'febuxostat', 'minor', 'Dois inibidores da xantina-oxidase: sem benefício e com risco aumentado de reações de hipersensibilidade.', 'Two xanthine oxidase inhibitors: no benefit and increased risk of hypersensitivity reactions.', 'Sobreposição do mecanismo de ação (inibição da xantina-oxidase) e do perfil de reações adversas cutâneas graves.', 'Overlapping mechanism (xanthine oxidase inhibition) and risk profile of severe cutaneous reactions.', 'Não associar; escolher apenas um inibidor da xantina-oxidase.', 'Do not combine; choose only one xanthine oxidase inhibitor.', 'Vigiar erupções cutâneas e sintomas de hipersensibilidade.', 'Watch for skin rash and hypersensitivity symptoms.', 'Erupção cutânea, prurido, febre, sintomas de síndrome de hipersensibilidade.', 'Skin rash, pruritus, fever, hypersensitivity syndrome symptoms.', 'DailyMed (FDA) — rótulo aprovado Alopurinol: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=b6c5b5c0-b1cb-44c0-a849-5d317e6fa300 ; rótulo aprovado Febuxostat: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=f2c338dc-5bab-49f4-a4ac-d8dea8afeea5 — referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)', 'DailyMed (FDA) — approved Allopurinol label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=b6c5b5c0-b1cb-44c0-a849-5d317e6fa300 ; approved Febuxostat label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=f2c338dc-5bab-49f4-a4ac-d8dea8afeea5 — additional reference: Prontuário Terapêutico do INFARMED (11th ed., 2012)'),
  ('leflunomida', 'warfarina', 'moderate', 'Leflunomida + anticoagulante: possível aumento do efeito anticoagulante.', 'Leflunomida + anticoagulant: possible increased anticoagulant effect.', 'A leflunomida pode inibir o metabolismo da varfarina, elevando o INR.', 'Leflunomide may inhibit warfarin metabolism, raising INR.', 'Monitorizar INR após início ou alteração de dose de leflunomida.', 'Monitor INR after starting or changing leflunomide dose.', 'INR periódico durante a associação.', 'Periodic INR during the combination.', 'Hemorragia, equimoses espontâneas.', 'Bleeding, spontaneous ecchymosis.', 'DailyMed (FDA) — rótulo aprovado Leflunomida: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=fc044417-cd9a-42f6-8a3d-a14e7c2f81a2 ; rótulo aprovado Varfarina: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=541c9a70-adaf-4ef3-94ba-ad4e70dfa057 — referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)', 'DailyMed (FDA) — approved Leflunomide label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=fc044417-cd9a-42f6-8a3d-a14e7c2f81a2 ; approved Warfarin label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=541c9a70-adaf-4ef3-94ba-ad4e70dfa057 — additional reference: Prontuário Terapêutico do INFARMED (11th ed., 2012)'),
  ('leflunomida', 'metotrexato', 'moderate', 'Leflunomida + metotrexato: risco acrescido de hepatotoxicidade e mielossupressão.', 'Leflunomide + methotrexate: increased risk of hepatotoxicity and marrow suppression.', 'Efeitos tóxicos aditivos sobre o fígado e a medula óssea.', 'Additive toxic effects on the liver and bone marrow.', 'A associação só em contexto especializado, com monitorização apertada de transaminases e hemograma.', 'Combination only in specialist settings, with tight monitoring of transaminases and full blood count.', 'Transaminases e hemograma mensais; função renal.', 'Transaminases and full blood count monthly; renal function.', 'Icterícia, febre, infeções, úlceras orais.', 'Jaundice, fever, infections, oral ulcers.', 'DailyMed (FDA) — rótulo aprovado Leflunomida: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=fc044417-cd9a-42f6-8a3d-a14e7c2f81a2 ; rótulo aprovado Metotrexato: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=757d6cef-6696-7a1c-8074-01258aaa8bdd — referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)', 'DailyMed (FDA) — approved Leflunomide label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=fc044417-cd9a-42f6-8a3d-a14e7c2f81a2 ; approved Methotrexate label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=757d6cef-6696-7a1c-8074-01258aaa8bdd — additional reference: Prontuário Terapêutico do INFARMED (11th ed., 2012)'),
  ('hidroxicloroquina', 'aspirina', 'minor', 'Hidroxicloroquina + aspirina: risco gastrointestinal aditivo.', 'Hydroxychloroquine + aspirin: additive gastrointestinal risk.', 'Ambos podem irritar a mucosa gástrica.', 'Both may irritate the gastric mucosa.', 'Vigiar sintomas dispépticos; considerar gastroprotecção em doentes de risco.', 'Watch for dyspeptic symptoms; consider gastroprotection in at-risk patients.', 'Sintomas GI após a associação.', 'GI symptoms after the combination.', 'Dispepsia, dor epigástrica, melena.', 'Dyspepsia, epigastric pain, melena.', 'DailyMed (FDA) — rótulo aprovado Hidroxicloroquina: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=da435181-0c5a-4188-8d59-51234116b005 ; rótulo aprovado Ácido acetilsalicílico: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=3ba0a9f2-062a-401e-82eb-54383a822366 — referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)', 'DailyMed (FDA) — approved Hydroxychloroquine label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=da435181-0c5a-4188-8d59-51234116b005 ; approved Aspirin label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=3ba0a9f2-062a-401e-82eb-54383a822366 — additional reference: Prontuário Terapêutico do INFARMED (11th ed., 2012)')
) AS v(slug_a, slug_b, severity, summary_pt, summary_en,
       mechanism_pt, mechanism_en, management_pt, management_en,
       monitoring_pt, monitoring_en, red_flags_pt, red_flags_en,
       source_pt, source_en)
JOIN public.drugs a ON a.slug = v.slug_a
JOIN public.drugs b ON b.slug = v.slug_b
ON CONFLICT (drug_a_id, drug_b_id) DO NOTHING;

