FROM public.drugs d
JOIN (VALUES
  ('naproxeno', 'alcool', 'Álcool', 'Alcohol', 'moderate', 'O álcool agrava a irritação da mucosa gástrica e o risco hemorrágico associado aos AINE.', 'Alcohol worsens gastric mucosal irritation and the bleeding risk associated with NSAIDs.', 'Limitar ou evitar o consumo de álcool durante o tratamento.', 'Limit or avoid alcohol during treatment.', 'EMC-UK (MHRA) — SmPC aprovada Naproxeno: https://www.medicines.org.uk/emc/product/13237/smpc', 'EMC-UK (MHRA) — approved Naproxen SmPC: https://www.medicines.org.uk/emc/product/13237/smpc', 1),
  ('naproxeno', 'alimentos', 'Alimentos', 'Food', 'minor', 'Os alimentos retardam a absorção mas reduzem a irritação gástrica.', 'Food slows absorption but reduces gastric irritation.', 'Tomar com alimentos ou leite para reduzir o desconforto gástrico.', 'Take with food or milk to reduce stomach discomfort.', 'EMC-UK (MHRA) — SmPC aprovada Naproxeno: https://www.medicines.org.uk/emc/product/13237/smpc', 'EMC-UK (MHRA) — approved Naproxen SmPC: https://www.medicines.org.uk/emc/product/13237/smpc', 1),
  ('celecoxib', 'alcool', 'Álcool', 'Alcohol', 'moderate', 'O álcool aumenta o risco de irritação/hemorragia gástrica.', 'Alcohol increases the risk of gastric irritation/bleeding.', 'Evitar álcool durante o tratamento.', 'Avoid alcohol during treatment.', 'EMC-UK (MHRA) — SmPC aprovada Celecoxib: https://www.medicines.org.uk/emc/product/5533/smpc', 'EMC-UK (MHRA) — approved Celecoxib SmPC: https://www.medicines.org.uk/emc/product/5533/smpc', 1),
  ('celecoxib', 'alimentos', 'Alimentos', 'Food', 'minor', 'A toma com alimentos pode atrasar ligeiramente a absorção sem afetar a eficácia.', 'Taking with food may slightly delay absorption without affecting efficacy.', 'Pode tomar com alimentos se houver desconforto gástrico.', 'May take with food if stomach discomfort occurs.', 'EMC-UK (MHRA) — SmPC aprovada Celecoxib: https://www.medicines.org.uk/emc/product/5533/smpc', 'EMC-UK (MHRA) — approved Celecoxib SmPC: https://www.medicines.org.uk/emc/product/5533/smpc', 1),
  ('metotrexato', 'alcool', 'Álcool', 'Alcohol', 'moderate', 'O álcool potencia a hepatotoxicidade do metotrexato.', 'Alcohol potentiates methotrexate hepatotoxicity.', 'Evitar álcool durante o tratamento (risco hepático aditivo).', 'Avoid alcohol during treatment (additive liver risk).', 'EMC-UK (MHRA) — SmPC aprovada Metotrexato: https://www.medicines.org.uk/emc/product/511/smpc', 'EMC-UK (MHRA) — approved Methotrexate SmPC: https://www.medicines.org.uk/emc/product/511/smpc', 1),
  ('metotrexato', 'alimentos', 'Alimentos', 'Food', 'minor', 'A toma com alimentos reduz as náuseas associadas ao metotrexato.', 'Taking with food reduces methotrexate-related nausea.', 'Tomar com alimentos para melhorar a tolerância gastrointestinal.', 'Take with food to improve GI tolerance.', 'EMC-UK (MHRA) — SmPC aprovada Metotrexato: https://www.medicines.org.uk/emc/product/511/smpc', 'EMC-UK (MHRA) — approved Methotrexate SmPC: https://www.medicines.org.uk/emc/product/511/smpc', 1),
  ('leflunomida', 'alcool', 'Álcool', 'Alcohol', 'moderate', 'O álcool aumenta o risco de lesão hepática.', 'Alcohol increases the risk of liver injury.', 'Evitar álcool durante o tratamento.', 'Avoid alcohol during treatment.', 'EMC-UK (MHRA) — SmPC aprovada Leflunomida: https://www.medicines.org.uk/emc/product/4944/smpc', 'EMC-UK (MHRA) — approved Leflunomide SmPC: https://www.medicines.org.uk/emc/product/4944/smpc', 1),
  ('colchicina', 'toranja', 'Toranja', 'Grapefruit', 'moderate', 'A toranja inibe o CYP3A4 e a glicoproteína-P, elevando as concentrações de colchicina.', 'Grapefruit inhibits CYP3A4 and P-glycoprotein, raising colchicine concentrations.', 'Evitar sumo de toranja durante o tratamento.', 'Avoid grapefruit juice during treatment.', 'EMC-UK (MHRA) — SmPC aprovada Colchicina: https://www.medicines.org.uk/emc/product/14362/smpc', 'EMC-UK (MHRA) — approved Colchicine SmPC: https://www.medicines.org.uk/emc/product/14362/smpc', 1),
  ('colchicina', 'alcool', 'Álcool', 'Alcohol', 'minor', 'O álcool pode aumentar os efeitos gastrointestinais da colchicina.', 'Alcohol may increase the GI effects of colchicine.', 'Limitar o consumo de álcool.', 'Limit alcohol intake.', 'EMC-UK (MHRA) — SmPC aprovada Colchicina: https://www.medicines.org.uk/emc/product/14362/smpc', 'EMC-UK (MHRA) — approved Colchicine SmPC: https://www.medicines.org.uk/emc/product/14362/smpc', 1),
  ('febuxostat', 'alcool', 'Álcool', 'Alcohol', 'moderate', 'O álcool aumenta a uricemia e pode precipitar crises de gota.', 'Alcohol raises serum urate and may trigger gout flares.', 'Limitar ou evitar álcool, sobretudo cerveja, durante o tratamento.', 'Limit or avoid alcohol, especially beer, during treatment.', 'EMC-UK (MHRA) — SmPC aprovada Febuxostat: https://www.medicines.org.uk/emc/product/487/smpc', 'EMC-UK (MHRA) — approved Febuxostat SmPC: https://www.medicines.org.uk/emc/product/487/smpc', 1),
  ('febuxostat', 'alimentos', 'Alimentos', 'Food', 'minor', 'Os alimentos não alteram de forma relevante a absorção.', 'Food does not significantly alter absorption.', 'Pode tomar com ou sem alimentos.', 'May take with or without food.', 'EMC-UK (MHRA) — SmPC aprovada Febuxostat: https://www.medicines.org.uk/emc/product/487/smpc', 'EMC-UK (MHRA) — approved Febuxostat SmPC: https://www.medicines.org.uk/emc/product/487/smpc', 1),
  ('alendronato', 'leite_calcio', 'Leite e laticínios', 'Milk and dairy products', 'moderate', 'O cálcio dos laticínios liga-se ao alendronato e impede a sua absorção.', 'Calcium in dairy binds alendronate and prevents its absorption.', 'Não tomar com leite, iogurte ou derivados; tomar o alendronato em jejum com água simples e aguardar 30-60 min.', 'Do not take with milk, yoghurt or dairy; take alendronate on an empty stomach with plain water and wait 30-60 min.', 'EMC-UK (MHRA) — SmPC aprovada Alendronato: https://www.medicines.org.uk/emc/product/5206/smpc', 'EMC-UK (MHRA) — approved Alendronate SmPC: https://www.medicines.org.uk/emc/product/5206/smpc', 1),
  ('alendronato', 'alimentos', 'Alimentos', 'Food', 'moderate', 'Os alimentos, sobretudo os ricos em cálcio, reduzem marcadamente a absorção.', 'Food, especially calcium-rich food, markedly reduces absorption.', 'Tomar o alendronato em jejum (ao acordar) com água simples e não comer durante 30-60 min.', 'Take alendronate fasting (on waking) with plain water and do not eat for 30-60 min.', 'EMC-UK (MHRA) — SmPC aprovada Alendronato: https://www.medicines.org.uk/emc/product/5206/smpc', 'EMC-UK (MHRA) — approved Alendronate SmPC: https://www.medicines.org.uk/emc/product/5206/smpc', 1),
  ('calcitriol', 'alimentos', 'Alimentos ricos em cálcio', 'Calcium-rich food', 'minor', 'Dieta rica em cálcio adiciona-se ao efeito do calcitriol sobre a calcemia.', 'Calcium-rich diet adds to calcitriol effect on serum calcium.', 'Manter ingestão de cálcio equilibrada e vigiar calcemia na suplementação conjunta.', 'Keep calcium intake balanced and monitor serum calcium with concurrent supplementation.', 'EMC-UK (MHRA) — SmPC aprovada Calcitriol: https://www.medicines.org.uk/emc/product/101902/smpc', 'EMC-UK (MHRA) — approved Calcitriol SmPC: https://www.medicines.org.uk/emc/product/101902/smpc', 1),
  ('aspirina', 'alcool', 'Álcool', 'Alcohol', 'moderate', 'O álcool aumenta o risco de irritação e hemorragia gástrica.', 'Alcohol increases the risk of gastric irritation and bleeding.', 'Evitar álcool, sobretudo em dose anti-inflamatória ou em doentes de risco.', 'Avoid alcohol, especially at anti-inflammatory doses or in at-risk patients.', 'EMC-UK (MHRA) — SmPC aprovada Ácido acetilsalicílico: https://www.medicines.org.uk/emc/product/8627/smpc', 'EMC-UK (MHRA) — approved Aspirin SmPC: https://www.medicines.org.uk/emc/product/8627/smpc', 1),
