  ('prednisolona', 'diabetes_mellitus', 'Diabetes mellitus', 'Diabetes mellitus', 'precaution', 'moderate', 'Os corticosteroides elevam a glicemia.', 'Corticosteroids raise blood glucose.', 'Monitorizar glicemia e ajustar antidiabéticos durante a terapêutica.', 'Monitor blood glucose and adjust antidiabetics during therapy.', 'EMC-UK (MHRA) — SmPC aprovada Prednisolona: https://www.medicines.org.uk/emc/product/2427/smpc', 'EMC-UK (MHRA) — approved Prednisolone SmPC: https://www.medicines.org.uk/emc/product/2427/smpc', 1),
  ('prednisolona', 'osteoporose', 'Osteoporose', 'Osteoporosis', 'precaution', 'moderate', 'O uso prolongado de corticosteroides acelera a perda óssea.', 'Long-term corticosteroids accelerate bone loss.', 'Usar a menor dose/duração; considerar cálcio + vitamina D e vigiar densidade óssea.', 'Use the lowest dose/duration; consider calcium + vitamin D and monitor bone density.', 'EMC-UK (MHRA) — SmPC aprovada Prednisolona: https://www.medicines.org.uk/emc/product/2427/smpc', 'EMC-UK (MHRA) — approved Prednisolone SmPC: https://www.medicines.org.uk/emc/product/2427/smpc', 1),
  ('prednisolona', 'glaucoma', 'Glaucoma', 'Glaucoma', 'precaution', 'moderate', 'Os corticosteroides podem elevar a pressão intraocular.', 'Corticosteroids may raise intraocular pressure.', 'Monitorizar pressão intraocular em terapêuticas prolongadas.', 'Monitor intraocular pressure on long-term therapy.', 'EMC-UK (MHRA) — SmPC aprovada Prednisolona: https://www.medicines.org.uk/emc/product/2427/smpc', 'EMC-UK (MHRA) — approved Prednisolone SmPC: https://www.medicines.org.uk/emc/product/2427/smpc', 1),
  ('hidroxicloroquina', 'doenca_retina', 'Doença da retina (maculopatia)', 'Retinal disease (maculopathy)', 'precaution', 'moderate', 'A hidroxicloroquina pode causar retinopatia cumulativa irreversível.', 'Hydroxychloroquine may cause cumulative irreversible retinopathy.', 'Avaliação oftalmológica basal e periódica (sobretudo > 5 anos ou fator de risco).', 'Baseline and periodic ophthalmological review (especially > 5 years or risk factors).', 'EMC-UK (MHRA) — SmPC aprovada Hidroxicloroquina: https://www.medicines.org.uk/emc/product/11540/smpc', 'EMC-UK (MHRA) — approved Hydroxychloroquine SmPC: https://www.medicines.org.uk/emc/product/11540/smpc', 1),
  ('hidroxicloroquina', 'doenca_hepatica_ativa', 'Doença hepática ativa', 'Active liver disease', 'precaution', 'moderate', 'O metabolismo hepático reduzido pode aumentar a exposição.', 'Reduced hepatic metabolism may increase exposure.', 'Usar com precaução e monitorizar função hepática.', 'Use with caution and monitor liver function.', 'EMC-UK (MHRA) — SmPC aprovada Hidroxicloroquina: https://www.medicines.org.uk/emc/product/11540/smpc', 'EMC-UK (MHRA) — approved Hydroxychloroquine SmPC: https://www.medicines.org.uk/emc/product/11540/smpc', 1)
) AS v(slug, condition_slug, condition_pt, condition_en, interaction_type, severity,
       reason_pt, reason_en, advice_pt, advice_en,
       source_pt, source_en, sort_order)
ON d.slug = v.slug
ON CONFLICT (drug_id, condition_slug) DO NOTHING;

-- ----------------------------------------------------------------
-- 5. Gestação / Lactação (drug_pregnancy_info, 1:1 por fármaco)
-- ----------------------------------------------------------------
INSERT INTO public.drug_pregnancy_info
  (drug_id, pregnancy_category, risk_pt, risk_en, trimester_pt, trimester_en,
   lactation_pt, lactation_en, contraception_pt, contraception_en,
   source_pt, source_en, status)
SELECT d.id, v.pregnancy_category, v.risk_pt, v.risk_en, v.trimester_pt, v.trimester_en,
       v.lactation_pt, v.lactation_en, v.contraception_pt, v.contraception_en,
       v.source_pt, v.source_en, 'published'
FROM public.drugs d
JOIN (VALUES
  ('naproxeno', 'caution', 'Os AINE devem ser evitados no 3.º trimestre (fecho prematuro do canal arterial, oligohidrâmnios). Uso ocasional no 1.º/2.º trimestre com precaução.', 'NSAIDs should be avoided in the 3rd trimester (premature ductus arteriosus closure, oligohydramnios). Occasional use in 1st/2nd trimester with caution.', 'Evitar no 3.º trimestre; usar a menor dose pelo menor tempo possível no 1.º/2.º trimestre.', 'Avoid in the 3rd trimester; use the lowest dose for the shortest time in the 1st/2nd trimester.', 'Preferir paracetamol na gravidez quando indicado.', 'Prefer paracetamol in pregnancy when indicated.', 'A concentração no leite é baixa; uso ocasional compatível com vigilância do lactente.', 'Milk levels are low; occasional use is compatible with infant monitoring.', 'EMC-UK (MHRA) — SmPC aprovada Naproxeno: https://www.medicines.org.uk/emc/product/13237/smpc', 'EMC-UK (MHRA) — approved Naproxen SmPC: https://www.medicines.org.uk/emc/product/13237/smpc'),
  ('celecoxib', 'caution', 'O celecoxib (AINE) deve ser evitado no 3.º trimestre; dados limitados no início da gravidez.', 'Celecoxib (NSAID) should be avoided in the 3rd trimester; limited data in early pregnancy.', 'Evitar no 3.º trimestre; evitar em mulheres que tentam engravidar (possível efeito na ovulação).', 'Avoid in the 3rd trimester; avoid in women trying to conceive (possible effect on ovulation).', 'Preferir paracetamol na gravidez.', 'Prefer paracetamol in pregnancy.', 'Dados limitados; preferir evitar durante a amamentação.', 'Limited data; prefer to avoid during breastfeeding.', 'EMC-UK (MHRA) — SmPC aprovada Celecoxib: https://www.medicines.org.uk/emc/product/5533/smpc', 'EMC-UK (MHRA) — approved Celecoxib SmPC: https://www.medicines.org.uk/emc/product/5533/smpc'),
  ('metotrexato', 'contraindicated', 'O metotrexato é teratogénico e abortivo; está contraindicado na gravidez e na conceção planeada.', 'Methotrexate is teratogenic and abortifacient; contraindicated in pregnancy and planned conception.', 'Contraindicado; usar contraceção eficaz durante e até 3-6 meses após o tratamento (homens: 3 meses).', 'Contraindicated; use effective contraception during and up to 3-6 months after treatment (men: 3 months).', 'Contraindicado na amamentação.', 'Contraindicated during breastfeeding.', 'Contraceção eficaz obrigatória durante e até 3-6 meses após a terapêutica.', 'Effective contraception mandatory during and up to 3-6 months after therapy.', 'EMC-UK (MHRA) — SmPC aprovada Metotrexato: https://www.medicines.org.uk/emc/product/511/smpc', 'EMC-UK (MHRA) — approved Methotrexate SmPC: https://www.medicines.org.uk/emc/product/511/smpc'),
  ('leflunomida', 'contraindicated', 'A leflunomida é teratogénica; está contraindicada na gravidez.', 'Leflunomide is teratogenic; contraindicated in pregnancy.', 'Contraindicado; contraceção eficaz obrigatória e procedimento de washout (colestiramina) antes da conceção.', 'Contraindicated; mandatory effective contraception and washout procedure (cholestyramine) before conception.', 'Contraindicado na amamentação.', 'Contraindicated during breastfeeding.', 'Contraceção eficaz obrigatória; washout com colestiramina antes de engravidar.', 'Effective contraception mandatory; cholestyramine washout before pregnancy.', 'EMC-UK (MHRA) — SmPC aprovada Leflunomida: https://www.medicines.org.uk/emc/product/4944/smpc', 'EMC-UK (MHRA) — approved Leflunomide SmPC: https://www.medicines.org.uk/emc/product/4944/smpc'),
  ('colchicina', 'caution', 'Dados limitados; doses baixas parecem ter baixo risco, mas a exposição deve ser minimizada.', 'Limited data; low doses appear to carry low risk, but exposure should be minimised.', 'Usar apenas se claramente necessário e à menor dose, sobretudo no 1.º trimestre.', 'Use only if clearly necessary and at the lowest dose, especially in the 1st trimester.', 'Dados limitados; preferir evitar durante a amamentação.', 'Limited data; prefer to avoid during breastfeeding.', 'Não há recomendação formal de contraceção, mas minimizar a exposição.', 'No formal contraception requirement, but minimise exposure.', 'EMC-UK (MHRA) — SmPC aprovada Colchicina: https://www.medicines.org.uk/emc/product/14362/smpc', 'EMC-UK (MHRA) — approved Colchicine SmPC: https://www.medicines.org.uk/emc/product/14362/smpc'),
  ('febuxostat', 'no_data', 'Não existem dados suficientes em humanos; estudos animais mostraram efeitos adversos.', 'No adequate human data; animal studies showed adverse effects.', 'Evitar durante a gravidez, exceto se o benefício justificar o risco.', 'Avoid during pregnancy unless benefit justifies risk.', 'Desconhecido; preferir evitar durante a amamentação.', 'Unknown; prefer to avoid during breastfeeding.', 'Usar contraceção eficaz dadas as incertezas quanto ao risco.', 'Use effective contraception given uncertainty about risk.', 'EMC-UK (MHRA) — SmPC aprovada Febuxostat: https://www.medicines.org.uk/emc/product/487/smpc', 'EMC-UK (MHRA) — approved Febuxostat SmPC: https://www.medicines.org.uk/emc/product/487/smpc'),
  ('alendronato', 'contraindicated', 'Os bifosfonatos não são recomendados na gravidez (longa semi-vida e deposição óssea).', 'Bisphosphonates are not recommended in pregnancy (long half-life and bone deposition).', 'Evitar na gravidez; descontinuar antes de uma gravidez planeada se clinicamente possível.', 'Avoid in pregnancy; discontinue before planned conception if clinically possible.', 'Desconhecido; preferir evitar durante a amamentação.', 'Unknown; prefer to avoid during breastfeeding.', 'Descontinuar antes de gravidez planeada; usar contraceção eficaz.', 'Discontinue before planned pregnancy; use effective contraception.', 'EMC-UK (MHRA) — SmPC aprovada Alendronato: https://www.medicines.org.uk/emc/product/5206/smpc', 'EMC-UK (MHRA) — approved Alendronate SmPC: https://www.medicines.org.uk/emc/product/5206/smpc'),
  ('calcitriol', 'caution', 'O calcitriol em doses suprafisiológicas pode ser teratogénico; em doses de reposição o risco é baixo, vigiando a calcemia.', 'Calcitriol at supraphysiological doses may be teratogenic; at replacement doses the risk is low, monitoring serum calcium.', 'Usar apenas se necessário, com monitorização da calcemia.', 'Use only if necessary, with serum calcium monitoring.', 'Compatível na amamentação em doses de reposição, com vigilância do lactente.', 'Compatible during breastfeeding at replacement doses, with infant monitoring.', 'Em doses de reposição não é exigido recurso contracetivo; manter cautela com doses altas.', 'At replacement doses no contraception requirement; caution with high doses.', 'EMC-UK (MHRA) — SmPC aprovada Calcitriol: https://www.medicines.org.uk/emc/product/101902/smpc', 'EMC-UK (MHRA) — approved Calcitriol SmPC: https://www.medicines.org.uk/emc/product/101902/smpc'),
  ('aspirina', 'caution', 'A aspirina em dose antiagregante é usada em situações específicas; em dose analgésica deve ser evitada no 3.º trimestre.', 'Aspirin at antiplatelet dose is used in specific settings; at analgesic dose should be avoided in the 3rd trimester.', 'Manter apenas sob indicação médica (ex.: pré-eclâmpsia); evitar dose analgésica no 3.º trimestre.', 'Keep only on medical indication (e.g. pre-eclampsia); avoid analgesic dose in the 3rd trimester.', 'Dose única ocasional compatível; doses repetidas devem ser evitadas.', 'Occasional single dose is compatible; repeated doses should be avoided.', 'Contraceção não é suprimida; manter apenas por indicação médica.', 'No specific contraception; keep only on medical indication.', 'EMC-UK (MHRA) — SmPC aprovada Ácido acetilsalicílico: https://www.medicines.org.uk/emc/product/8627/smpc', 'EMC-UK (MHRA) — approved Aspirin SmPC: https://www.medicines.org.uk/emc/product/8627/smpc'),
  ('ibuprofeno', 'caution', 'Evitar no 3.º trimestre (fecho do canal arterial, oligohidrâmnios). Uso ocasional no 1.º/2.º trimestre com precaução.', 'Avoid in the 3rd trimester (ductus arteriosus closure, oligohydramnios). Occasional use in 1st/2nd trimester with caution.', 'Evitar no 3.º trimestre; usar a menor dose pelo menor tempo possível.', 'Avoid in the 3rd trimester; use the lowest dose for the shortest time.', 'Concentração no leite baixa; uso ocasional compatível.', 'Low milk levels; occasional use is compatible.', 'Usar paracetamol na gravidez; não há exigência específica de contraceção.', 'Use paracetamol in pregnancy; no specific contraception.', 'EMC-UK (MHRA) — SmPC aprovada Ibuprofeno: https://www.medicines.org.uk/emc/product/6713/smpc', 'EMC-UK (MHRA) — approved Ibuprofen SmPC: https://www.medicines.org.uk/emc/product/6713/smpc'),
  ('diclofenac', 'caution', 'Evitar no 3.º trimestre; dados limitados no início da gravidez.', 'Avoid in the 3rd trimester; limited data in early pregnancy.', 'Evitar no 3.º trimestre; usar a menor dose possível.', 'Avoid in the 3rd trimester; use the lowest dose possible.', 'Dados limitados; uso ocasional provavelmente compatível.', 'Limited data; occasional use probably compatible.', 'Usar paracetamol se possível; não há exigência específica de contraceção.', 'Use paracetamol where possible; no specific contraception.', 'EMC-UK (MHRA) — SmPC aprovada Diclofenac: https://www.medicines.org.uk/emc/product/4333/smpc', 'EMC-UK (MHRA) — approved Diclofenac SmPC: https://www.medicines.org.uk/emc/product/4333/smpc'),
  ('alopurinol', 'caution', 'Dados limitados; uso durante a gravidez apenas se o benefício justificar o risco.', 'Limited data; use in pregnancy only if benefit justifies risk.', 'Usar apenas se necessário, na menor dose eficaz.', 'Use only if necessary, at the lowest effective dose.', 'Dados limitados; preferir evitar durante a amamentação.', 'Limited data; prefer to avoid during breastfeeding.', 'Manter contraceção eficaz; dados limitados na conceção.', 'Maintain effective contraception; limited conception data.', 'EMC-UK (MHRA) — SmPC aprovada Alopurinol: https://www.medicines.org.uk/emc/product/100235/smpc', 'EMC-UK (MHRA) — approved Allopurinol SmPC: https://www.medicines.org.uk/emc/product/100235/smpc'),
  ('azatioprina', 'caution', 'Usado em situações específicas (transplantes, doenças autoimunes) quando o benefício supera o risco.', 'Used in specific settings (transplants, autoimmune diseases) when benefit outweighs risk.', 'Manter apenas sob vigilância especializada; não iniciar sem indicação clara.', 'Keep only under specialist supervision; do not start without clear indication.', 'Dados limitados; preferir evitar, embora seja por vezes mantido em mães transplantadas.', 'Limited data; prefer to avoid, though sometimes kept in transplanted mothers.', 'Planear a gravidez com a equipa médica antes de suspender/continuar.', 'Plan pregnancy with the specialist team before stopping/continuing.', 'EMC-UK (MHRA) — SmPC aprovada Azatioprina: https://www.medicines.org.uk/emc/product/14296/smpc', 'EMC-UK (MHRA) — approved Azathioprine SmPC: https://www.medicines.org.uk/emc/product/14296/smpc'),
  ('prednisolona', 'caution', 'Os corticosteroides atravessam a placenta; risco baixo com doses baixas, mas associados a fenda palatina (pequeno aumento) no 1.º trimestre e retardo do crescimento com uso prolongado.', 'Corticosteroids cross the placenta; low risk at low doses, but associated with cleft palate (small increase) in the 1st trimester and growth restriction with prolonged use.', 'Usar a menor dose eficaz e a mais curta duração; monitorizar crescimento fetal.', 'Use the lowest effective dose for the shortest duration; monitor fetal growth.', 'Baixas doses compatíveis com amamentação; doses elevadas: aguardar 3-4 h após a toma.', 'Low doses are compatible with breastfeeding; high doses: wait 3-4 h after dosing.', 'Contraceção não é requerida de rotina; planear com o médico, sobretudo em terapêutica prolongada.', 'No routine contraception needed; plan with the doctor, especially long-term therapy.', 'EMC-UK (MHRA) — SmPC aprovada Prednisolona: https://www.medicines.org.uk/emc/product/2427/smpc', 'EMC-UK (MHRA) — approved Prednisolone SmPC: https://www.medicines.org.uk/emc/product/2427/smpc'),
  ('hidroxicloroquina', 'caution', 'Usada habitualmente em lúpus durante a gravidez (reduz surtos); benefício geralmente supera o risco.', 'Routinely used in lupus during pregnancy (reduces flares); benefit usually outweighs risk.', 'Manter sob vigilância especializada; não suspender em lúpus sem indicação médica.', 'Keep under specialist supervision; do not stop in lupus without medical advice.', 'Concentrações no leite baixas; considerado compatível com a amamentação.', 'Low milk levels; considered compatible with breastfeeding.', 'Planear a gravidez com a equipa; contraceção não é contraindicada.', 'Plan pregnancy with the team; contraception not contraindicated.', 'EMC-UK (MHRA) — SmPC aprovada Hidroxicloroquina: https://www.medicines.org.uk/emc/product/11540/smpc', 'EMC-UK (MHRA) — approved Hydroxychloroquine SmPC: https://www.medicines.org.uk/emc/product/11540/smpc')
) AS v(slug, pregnancy_category, risk_pt, risk_en, trimester_pt, trimester_en,
       lactation_pt, lactation_en, contraception_pt, contraception_en,
       source_pt, source_en)
ON d.slug = v.slug
ON CONFLICT (drug_id) DO NOTHING;